mapper.select:
SELECT lookup.company_code AS lookup_value , c.COMP_ID AS company_code , c.COMP_NAME AS company_full_name , c.COMP_SNAME AS company_short_name FROM (
SELECT CONCAT(#{code}, '') AS company_code
) lookup INNER JOIN ais_inv_ods.wind_compintroduction c ON c.COMP_ID = lookup.company_code

SELECT ranked.security_code , ranked.node_label FROM ( SELECT lookup.security_code , s.node_label , ROW_NUMBER() OVER (PARTITION BY lookup.input_order ORDER BY s.sort_order ASC, s.id ASC, al.submit_time DESC, al.id DESC) AS seq FROM (
SELECT CAST(#{idx} AS DECIMAL(10, 0)) AS input_order, CONCAT(#{code}, '') AS security_code
) lookup INNER JOIN ip_adjust_log al ON al.security_code = lookup.security_code INNER JOIN ip_adjust_step s ON s.adjust_batch_no = al.adjust_batch_no WHERE al.is_deleted = 0 AND al.audit_status IN ('00', '11') AND s.step_status = 'pending' ) ranked WHERE ranked.seq = 1

SELECT DISTINCT lookup.input_order , lookup.security_code , occupied.target_pool_id FROM (
SELECT CAST(#{idx} AS DECIMAL(10, 0)) AS input_order, CONCAT(#{code}, '') AS security_code
) lookup INNER JOIN ip_adjust_log manual_log ON manual_log.security_code = lookup.security_code INNER JOIN ip_adjust_log occupied ON occupied.adjust_batch_no = manual_log.adjust_batch_no AND occupied.audit_status IN ('00', '11') AND occupied.is_deleted = 0 WHERE manual_log.adjust_type = '手工调整' AND manual_log.audit_status IN ('00', '11') AND manual_log.is_deleted = 0 AND EXISTS ( SELECT 1 FROM ip_adjust_step pending_step WHERE pending_step.adjust_batch_no = manual_log.adjust_batch_no AND pending_step.step_status = 'pending' )

SELECT target_pool_id , COUNT(DISTINCT security_code) AS current_count FROM ip_pool_status WHERE audit_status = '20' AND is_deleted = 0 AND target_pool_id IN
#{poolId}
GROUP BY target_pool_id

SELECT DISTINCT pool_id
FROM ip_pool_open_day
WHERE pool_id IN

    #{poolId}

  AND begin_date <= #{today}
  AND end_date >= #{today}
  AND is_deleted = 0

SELECT lookup.security_code FROM (
SELECT CONCAT(#{code}, '') AS security_code
) lookup WHERE EXISTS ( SELECT 1 FROM ais_inv_ods.wind_cbondissuerrating r WHERE r.s_info_compcode = lookup.security_code AND r.b_info_creditratingagency IN
#{agencyCode}
AND r.ann_dt >= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 YEAR), '%Y%m%d') AND REGEXP_SUBSTR(TRIM(r.b_info_creditrating), '^(A+|B+|C+|D)[+-]?', 1, 1, 'c') IN ( 'AA-', 'A+', 'A', 'A-' , 'BBB+', 'BBB', 'BBB-' , 'BB+', 'BB', 'BB-', 'B+', 'B', 'B-' , 'CCC', 'CC', 'C', 'D' ) )
